 glossary=[G("Data leakage", "Information from validation or test data influencing training, giving over-optimistic results."), G("Baseline", "A simple reference model that a new method must outperform."), G("Train/validation/test split", "Dividing data for fitting, tuning and final evaluation."), G("Reproducibility", "The ability of others to rerun an analysis and get the same results."), G("Virtual environment", "An isolated Python installation with pinned package versions.")],
